. Sazali juga merupakan salah seorang ahli Persekutuan Bina Badan Malaysia. Sazali telah berjaya mewakili Malaysia dalam Sukan Asia 2006 di Doha, Qatar.','1967-08-08',NULL,'2',NULL),(3869303,'Fred Chong',NULL,'Production',NULL,'0.011',NULL,NULL,'0',NULL,'',NULL,NULL,'2',NULL),(3869305,'Allyan Too',NULL,'Production',NULL,'0.001',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3869306,'Euho',NULL,'Directing',NULL,'0.001',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3869311,'Vikar',NULL,'Acting',NULL,'0.001',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3869312,'Jazmy Juma',NULL,'Acting',NULL,'0.008',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3869315,'Evie Feroza',NULL,'Acting',NULL,'0.004',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3869316,'Sabronzo',NULL,'Acting',NULL,'0.001',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3869319,'Mark Oâ€™Dea','nm9987121','Acting','Gravesend, Kent, England','0.001',NULL,'https://image.tmdb.org/t/p/original/pM07g0jZhv5BQ3rBeK1EJ35ebtR.jpg','0',NULL,'','1991-06-01',NULL,'2',NULL),(3869323,'Eddie Chong',NULL,'Acting',NULL,'0.001',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3870752,'Jean Seizure',NULL,'Acting',NULL,'0.001',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3872774,'Ben Omar',NULL,'Writing',NULL,'0.003',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3872790,'Eriza Allya',NULL,'Acting',NULL,'0.035',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3872796,'Arnie Shasha',NULL,'Acting',NULL,'0.001',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3875985,'Atitaya Tribudarak',NULL,'Acting',NULL,'5.969',NULL,'https://image.tmdb.org/t/p/original/k1qWYWTT38PLWY5HmXv4sOOm8hz.jpg','0',NULL,'','1999-06-09',NULL,'1',NULL),(3881300,'Akmal Aziz Asmawi',NULL,'Directing',NULL,'0.001',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3887197,'Hayla Adzkiya',NULL,'Acting',NULL,'0.001',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3887243,'Firdaus Sufiyan',NULL,'Acting',NULL,'0.001',NULL,NULL,'0',NULL,'',NULL,NULL,'0',NULL),(3887281,'Yusran Hashim',NULL,'Acting',NULL,'0.001',NULL,NULL,'0